def extract_text(msg):
    if isinstance(msg, dict) and msg.get('text'):
        return msg['text']
    out=[]
    for b in msg.get('blocks', []) or []:
        for el in (b.get('elements') or []):
            for sec in (el.get('elements') or []):
                for leaf in (sec.get('elements') or []):
                    t=leaf.get('text')
                    if t:
                        out.append(t)
    return ''.join(out).strip()
