def extract_threads(results):
    out=[]
    for r in results:
        if r.get('tool_slug')=='SLACK_FETCH_MESSAGE_THREAD_FROM_A_CONVERSATION' and r.get('response',{}).get('successful'):
            out.append(r['response']['data']['messages'])
    return out
